  trustscore?: number
  isTopCandidate?: boolean
  applicationStatus?: "applied" | "screening" | "interview" | "offer" | "hired" | "rejected"
  lastActivity?: string
  email?: string
  phone?: string
}

export type MatchedCandidate = {
  candidate_id: number
  name: string
  avatar_url?: string
  headline?: string
  location?: string
  years_experience?: number
  omniscore: number
  score_tier?: string
  skills_summary?: string
  experience_summary?: string
  similarity_score: number
  weighted_score: number
  match_level: "excellent" | "good" | "fair" | "poor"
  matching_skills: string[]
  missing_skills: string[]
  skill_match_pct: number
  explanation: {
    semantic_match: string
    skills_match: string
    omniscore_boost: string
    company_trustscore: string
  }
}

export type Job = {
  id: number
  title: string
  company?: string
  location?: string
  salary_range?: string
  job_type?: string
  description?: string
  requirements?: string
  status: string
  application_count?: number
  views?: number
  interviews?: number
  created_at?: string
}

export type PipelineStats = {
  total: number
  new: number
