    type: "select" as const,
    options: [
      { value: "excellent", label: "Excellent (85%+" },
      { value: "good", label: "Good (70-84%)" },
      { value: "fair", label: "Fair (55-69%)" },
    ],
  },
  {
    id: "experience",
    label: "Experience",
    type: "select" as const,
    options: [
      { value: "0-2", label: "0-2 years" },
      { value: "3-5", label: "3-5 years" },
      { value: "6-10", label: "6-10 years" },
