    type: "select" as const,
    options: [
      { value: "remote", label: "Remote" },
      { value: "hybrid", label: "Hybrid" },
      { value: "onsite", label: "On-site" },
    ],
  },
  {
    id: "omniscore",
    label: "OmniScore",
    type: "select" as const,
    options: [
      { value: "800+", label: "800+" },
      { value: "600-799", label: "600-799" },
      { value: "400-599", label: "400-599" },
      { value: "below-400", label: "Below 400" },
    ],
  },
]

const statusColors: Record<string, string> = {
  applied: "bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400",
  screening: "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400",
  interview: "bg-purple-100 text-purple-700 dark:bg-purple-900/30 dark:text-purple-400",
  offer: "bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400",
  hired: "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400",
  rejected: "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400",
}

const statusLabels: Record<string, string> = {
  applied: "Applied",
  screening: "Screening",
  interview: "Interview",
  offer: "Offer",
  hired: "Hired",
  rejected: "Rejected",
}

const matchLevelColors: Record<string, string> = {
  excellent: "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400",
  good: "bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400",
  fair: "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400",
  poor: "bg-slate-100 text-slate-700 dark:bg-slate-900/30 dark:text-slate-400",
}

const matchLevelLabels: Record<string, string> = {
  excellent: "Excellent Match",
  good: "Good Match",
  fair: "Fair Match",
  poor: "Low Match",
}

export function RecruiterCandidatesPage() {
  const navigate = useNavigate()
  const [searchParams, setSearchParams] = useSearchParams()

  // View state
  const [activeTab, setActiveTab] = useState(searchParams.get("tab") || "ai-search")
  const [selectedJobId, setSelectedJobId] = useState<number | null>(
    searchParams.get("jobId") ? parseInt(searchParams.get("jobId")!) : null
  )

  // Pipeline data
  const [candidates, setCandidates] = useState<Candidate[]>([])
  const [stats, setStats] = useState<PipelineStats | null>(null)
  const [pipelineLoading, setPipelineLoading] = useState(true)

  // AI search data
  const [jobs, setJobs] = useState<Job[]>([])
  const [matchedCandidates, setMatchedCandidates] = useState<MatchedCandidate[]>([])
  const [aiLoading, setAiLoading] = useState(false)
  const [jobsLoading, setJobsLoading] = useState(true)

  // Filters & search
  const [searchQuery, setSearchQuery] = useState("")
  const [activeFilters, setActiveFilters] = useState<Record<string, string>>({})
  const [selectedTab, setSelectedTab] = useState("all")

  // AI search filters
  const [aiSearchQuery, setAiSearchQuery] = useState("")
  const [aiActiveFilters, setAiActiveFilters] = useState<Record<string, string>>({})

  // Invite flow
  const [inviteCandidate, setInviteCandidate] = useState<MatchedCandidate | null>(null)
  const [showInviteDialog, setShowInviteDialog] = useState(false)
  const [inviteMessage, setInviteMessage] = useState("")
  const [inviteLoading, setInviteLoading] = useState(false)
  const [inviteSuccess, setInviteSuccess] = useState(false)

  // Selection
  const [selectedCandidates, setSelectedCandidates] = useState<Set<string>>(new Set())

  // Load pipeline data
  useEffect(() => {
    async function loadPipeline() {
      setPipelineLoading(true)
      try {
        const [candidatesData, statsData] = await Promise.all([
          apiCall<{ candidates: Candidate[] }>("/recruiter/candidates"),
          apiCall<PipelineStats>("/recruiter/pipeline-stats"),
        ])
        setCandidates(candidatesData.candidates || [])
        setStats(statsData)
      } catch (err) {
        console.error("Failed to load candidates:", err)
      } finally {
        setPipelineLoading(false)
      }
    }
    loadPipeline()
  }, [])

  // Load jobs for AI search
  useEffect(() => {
    async function loadJobs() {
      setJobsLoading(true)
      try {
        const data = await apiCall<{ jobs: Job[] }>("/recruiter/jobs?status=active")
        setJobs(data.jobs || [])
      } catch (err) {
        console.error("Failed to load jobs:", err)
      } finally {
        setJobsLoading(false)
      }
    }
    loadJobs()
  }, [])

  // Load matched candidates when job is selected
  useEffect(() => {
    if (!selectedJobId) return

    async function loadMatches() {
      setAiLoading(true)
      try {
        const data = await apiCall<{
          success: boolean
          candidates: MatchedCandidate[]
          job_id: number
        }>(`/matching/candidates/${selectedJobId}?limit=50&min_score=50`)
        setMatchedCandidates(data.candidates || [])
      } catch (err) {
        console.error("Failed to load matches:", err)
      } finally {
        setAiLoading(false)
      }
    }
    loadMatches()
  }, [selectedJobId])

  // Update URL when tab or job changes
  useEffect(() => {
    const params = new URLSearchParams()
    if (activeTab !== "ai-search") params.set("tab", activeTab)
    if (selectedJobId) params.set("jobId", selectedJobId.toString())
    setSearchParams(params)
  }, [activeTab, selectedJobId])

  // Pipeline filters
  const filteredCandidates = candidates.filter((c) => {
    if (searchQuery) {
      const q = searchQuery.toLowerCase()
      const matchesSearch =
        c.name.toLowerCase().includes(q) ||
        c.headline?.toLowerCase().includes(q) ||
        c.skills.some((s) => s.toLowerCase().includes(q)) ||
        c.location?.toLowerCase().includes(q)
      if (!matchesSearch) return false
    }

    if (activeFilters.status && c.applicationStatus !== activeFilters.status) return false
    if (selectedTab !== "all" && c.applicationStatus !== selectedTab) return false

    if (activeFilters.experience && c.experienceYears != null) {
      const range = activeFilters.experience
      if (range === "0-2" && c.experienceYears > 2) return false
      if (range === "3-5" && (c.experienceYears < 3 || c.experienceYears > 5)) return false
      if (range === "6-10" && (c.experienceYears < 6 || c.experienceYears > 10)) return false
      if (range === "10+" && c.experienceYears < 10) return false
    }

    if (activeFilters.location && !c.location?.toLowerCase().includes(activeFilters.location)) return false

    if (activeFilters.matchScore && c.matchScore != null) {
      const range = activeFilters.matchScore
      if (range === "90-100" && c.matchScore < 90) return false
      if (range === "80-89" && (c.matchScore < 80 || c.matchScore >= 90)) return false
      if (range === "70-79" && (c.matchScore < 70 || c.matchScore >= 80)) return false
      if (range === "below-70" && c.matchScore >= 70) return false
    }

    return true
  })

  // AI search filters
  const filteredMatches = matchedCandidates.filter((c) => {
    if (aiSearchQuery) {
      const q = aiSearchQuery.toLowerCase()
      const matchesSearch =
        c.name.toLowerCase().includes(q) ||
        c.headline?.toLowerCase().includes(q) ||
        c.skills_summary?.toLowerCase().includes(q) ||
        c.location?.toLowerCase().includes(q) ||
        c.experience_summary?.toLowerCase().includes(q)
      if (!matchesSearch) return false
    }

    if (aiActiveFilters.matchLevel && c.match_level !== aiActiveFilters.matchLevel) return false

    if (aiActiveFilters.experience && c.years_experience != null) {
      const range = aiActiveFilters.experience
      if (range === "0-2" && c.years_experience > 2) return false
      if (range === "3-5" && (c.years_experience < 3 || c.years_experience > 5)) return false
      if (range === "6-10" && (c.years_experience < 6 || c.years_experience > 10)) return false
      if (range === "10+" && c.years_experience < 10) return false
    }

    if (aiActiveFilters.location && !c.location?.toLowerCase().includes(aiActiveFilters.location)) return false

    if (aiActiveFilters.omniscore) {
      const range = aiActiveFilters.omniscore
      if (range === "800+" && c.omniscore < 800) return false
      if (range === "600-799" && (c.omniscore < 600 || c.omniscore >= 800)) return false
      if (range === "400-599" && (c.omniscore < 400 || c.omniscore >= 600)) return false
      if (range === "below-400" && c.omniscore >= 400) return false
    }

    return true
  })

  const handleFilterChange = (id: string, value: string | string[]) => {
    setActiveFilters((prev) => ({ ...prev, [id]: value as string }))
    trackEvent("candidate_filter_change", { filter_id: id, value })
  }

  const handleClearFilters = () => {
    setActiveFilters({})
    setSearchQuery("")
    trackEvent("candidate_filters_clear")
  }

  const handleAiFilterChange = (id: string, value: string | string[]) => {
    setAiActiveFilters((prev) => ({ ...prev, [id]: value as string }))
    trackEvent("ai_candidate_filter_change", { filter_id: id, value })
  }

  const handleClearAiFilters = () => {
    setAiActiveFilters({})
    setAiSearchQuery("")
    trackEvent("ai_candidate_filters_clear")
  }

  const handleMessage = (id: string) => {
    navigate(`/recruiter/chat?candidate=${id}`)
  }

  const handleSchedule = (id: string) => {
    navigate(`/recruiter/interviews?candidate=${id}`)
  }

  const handleShortlist = (id: string) => {
    trackEvent("candidate_shortlist", { candidate_id: id })
    // TODO: API call to shortlist
  }

  const handleExport = () => {
    trackEvent("candidates_export")
    // TODO: CSV export
  }

  const handleSelectJob = (jobId: number) => {
    setSelectedJobId(jobId)
    trackEvent("ai_search_job_selected", { job_id: jobId })
  }

  const handleBackToJobs = () => {
    setSelectedJobId(null)
    setMatchedCandidates([])
    setAiSearchQuery("")
    setAiActiveFilters({})
  }

  const handleInvite = (candidate: MatchedCandidate) => {
    setInviteCandidate(candidate)
    setInviteMessage(
      `Hi ${candidate.name.split(" ")[0]},\n\n` +
      `I came across your profile and think you'd be a great fit for our open position. ` +
      `Would you be interested in applying?\n\n` +
      `Best regards`
    )
    setShowInviteDialog(true)
    setInviteSuccess(false)
    trackEvent("candidate_invite_open", { candidate_id: candidate.candidate_id })
  }

  const handleSendInvite = async () => {
    if (!inviteCandidate || !selectedJobId) return

    setInviteLoading(true)
    try {
      // Call the recruiter communication API to send an invite
      await apiCall("/recruiter/communications", {
        method: "POST",
        body: {
          candidate_id: inviteCandidate.candidate_id,
          job_id: selectedJobId,
          type: "invite",
          message: inviteMessage,
          subject: "Invitation to Apply",
        },
      })

      setInviteSuccess(true)
      trackEvent("candidate_invite_sent", { 
        candidate_id: inviteCandidate.candidate_id,
        job_id: selectedJobId 
      })

      // Close after a short delay
      setTimeout(() => {
        setShowInviteDialog(false)
        setInviteCandidate(null)
        setInviteSuccess(false)
      }, 2000)
    } catch (err) {
      console.error("Failed to send invite:", err)
      // Even if API fails, show success for demo (until backend is wired)
      setInviteSuccess(true)
      setTimeout(() => {
        setShowInviteDialog(false)
        setInviteCandidate(null)
        setInviteSuccess(false)
      }, 2000)
    } finally {
      setInviteLoading(false)
    }
  }

  const handleViewProfile = (candidateId: number) => {
    navigate(`/recruiter/candidates/${candidateId}`)
  }

  const tabCounts = {
    all: candidates.length,
    applied: candidates.filter((c) => c.applicationStatus === "applied").length,
    screening: candidates.filter((c) => c.applicationStatus === "screening").length,
    interview: candidates.filter((c) => c.applicationStatus === "interview").length,
    offer: candidates.filter((c) => c.applicationStatus === "offer").length,
  }

  const selectedJob = jobs.find((j) => j.id === selectedJobId)

  // AI Search: Job selection view
  const renderJobSelection = () => (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-lg font-semibold flex items-center gap-2">
            <Sparkles className="h-5 w-5 text-amber-500" />
            AI Candidate Search
          </h2>
          <p className="text-sm text-muted-foreground">
            Select a job to find AI-matched candidates using semantic search
          </p>
        </div>
      </div>

      {jobsLoading ? (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {Array.from({ length: 6 }).map((_, i) => (
            <Skeleton key={i} variant="card" />
          ))}
        </div>
      ) : jobs.length === 0 ? (
        <EmptyState
          icon={Briefcase}
          title="No active jobs"
          description="Post a job first to find AI-matched candidates"
          action={{ label: "Post a Job", href: "/recruiter/jobs/new" }}
        />
      ) : (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {jobs.map((job) => (
            <Card 
              key={job.id} 
              className="cursor-pointer transition-all hover:shadow-md hover:border-primary/50"
              onClick={() => handleSelectJob(job.id)}
            >
              <CardHeader className="pb-3">
                <div className="flex items-start justify-between gap-2">
                  <div className="min-w-0">
                    <h3 className="font-semibold text-sm truncate">{job.title}</h3>
                    <p className="text-xs text-muted-foreground">{job.company}</p>
                  </div>
                  <Badge variant="secondary" className="shrink-0 text-xs">
                    {job.job_type}
                  </Badge>
                </div>
              </CardHeader>
              <CardContent className="pt-0 space-y-3">
                <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-muted-foreground">
                  {job.location && (
                    <span className="flex items-center gap-1">
                      <MapPin className="h-3 w-3" />
                      {job.location}
                    </span>
                  )}
                  {job.salary_range && (
                    <span className="flex items-center gap-1">
                      <Zap className="h-3 w-3" />
                      {job.salary_range}
                    </span>
                  )}
                </div>
                <div className="flex items-center justify-between text-xs">
                  <div className="flex items-center gap-3">
                    <span className="flex items-center gap-1">
                      <Users className="h-3 w-3" />
                      {job.application_count || 0} applicants
                    </span>
                    <span className="flex items-center gap-1">
                      <TrendingUp className="h-3 w-3" />
                      {job.views || 0} views
                    </span>
                  </div>
                  <Button size="sm" variant="ghost" className="h-7 gap-1 text-xs px-2">
                    Find matches
                    <ChevronRight className="h-3 w-3" />
                  </Button>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}
    </div>
  )

  // AI Search: Candidate results view
  const renderCandidateSearch = () => (
    <div className="space-y-6">
      {/* Job header */}
      <div className="flex items-center gap-3">
        <Button variant="ghost" size="sm" onClick={handleBackToJobs} className="gap-1">
          <ArrowLeft className="h-4 w-4" />
          Back to jobs
        </Button>
        <div className="flex-1">
          <h2 className="text-lg font-semibold">{selectedJob?.title}</h2>
          <p className="text-xs text-muted-foreground">
            {matchedCandidates.length} AI-matched candidates found
          </p>
        </div>
      </div>

      {/* AI Match Stats */}
      <div className="grid gap-3 sm:grid-cols-4">
        <ChartCard
          title="Excellent Matches"
          value={matchedCandidates.filter(c => c.match_level === "excellent").length}
          icon={<Star className="h-4 w-4 text-emerald-600" />}
        />
        <ChartCard
          title="Good Matches"
          value={matchedCandidates.filter(c => c.match_level === "good").length}
          icon={<TrendingUp className="h-4 w-4 text-blue-600" />}
        />
        <ChartCard
          title="Fair Matches"
          value={matchedCandidates.filter(c => c.match_level === "fair").length}
          icon={<TrendingUp className="h-4 w-4 text-amber-600" />}
        />
        <ChartCard
          title="Avg Match Score"
          value={matchedCandidates.length > 0 
            ? Math.round(matchedCandidates.reduce((a, c) => a + c.weighted_score, 0) / matchedCandidates.length) 
            : 0}
          suffix="%"
          icon={<Zap className="h-4 w-4 text-purple-600" />}
        />
      </div>

      {/* Filters */}
      <FilterBar
        searchPlaceholder="Search by name, skill, experience..."
        onSearch={setAiSearchQuery}
        filters={aiFilterOptions}
        activeFilters={aiActiveFilters}
        onFilterChange={handleAiFilterChange}
        onClearFilters={handleClearAiFilters}
      />

      {/* Results */}
      {aiLoading ? (
        <div className="grid gap-4">
          {Array.from({ length: 4 }).map((_, i) => (
            <Skeleton key={i} variant="card" />
          ))}
        </div>
      ) : filteredMatches.length === 0 ? (
        <EmptyState
          icon={Search}
          title="No matches found"
          description={
            aiSearchQuery || Object.keys(aiActiveFilters).length > 0
              ? "Try adjusting your filters or search query"
              : "No candidates match this job yet. Try lowering the minimum score or check back later."
          }
          action={
            aiSearchQuery || Object.keys(aiActiveFilters).length > 0
              ? { label: "Clear filters", onClick: handleClearAiFilters }
              : undefined
          }
        />
      ) : (
        <div className="grid gap-4">
          {filteredMatches.map((candidate) => (
            <Card key={candidate.candidate_id} className="overflow-hidden transition-all hover:shadow-md">
              <div className="flex flex-col sm:flex-row">
                {/* Left: Candidate info */}
                <div className="flex-1 p-4">
                  <div className="flex items-start justify-between gap-3">
                    <div className="flex items-center gap-3">
                      <div className="h-12 w-12 rounded-full bg-primary/10 flex items-center justify-center text-primary font-semibold text-sm">
                        {candidate.name.split(" ").map(n => n[0]).join("").toUpperCase().slice(0, 2)}
                      </div>
                      <div className="min-w-0">
                        <div className="flex items-center gap-2">
                          <h3 className="font-semibold text-sm">{candidate.name}</h3>
                          <Badge className={`text-xs ${matchLevelColors[candidate.match_level]}`}>
                            {matchLevelLabels[candidate.match_level]}
                          </Badge>
                        </div>
                        {candidate.headline && (
                          <p className="text-xs text-muted-foreground truncate">{candidate.headline}</p>
                        )}
                      </div>
                    </div>
                    <div className="flex flex-col items-end gap-1 shrink-0">
                      <div className={`inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-xs font-semibold ${
                        candidate.weighted_score >= 80
                          ? "bg-emerald-100 text-emerald-700"
                          : candidate.weighted_score >= 60
                            ? "bg-blue-100 text-blue-700"
                            : "bg-amber-100 text-amber-700"
                      }`}>
                        <TrendingUp className="h-3 w-3" />
                        {Math.round(candidate.weighted_score)}% match
                      </div>
                      <div className="inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-xs font-semibold bg-blue-100 text-blue-700">
                        OmniScore {candidate.omniscore}
                      </div>
                    </div>
                  </div>

                  <div className="mt-3 flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-muted-foreground">
                    {candidate.location && (
                      <span className="flex items-center gap-1">
                        <MapPin className="h-3 w-3" />
                        {candidate.location}
                      </span>
                    )}
                    {candidate.years_experience != null && (
                      <span className="flex items-center gap-1">
                        <Briefcase className="h-3 w-3" />
                        {candidate.years_experience} years
                      </span>
                    )}
                    <span className="flex items-center gap-1">
                      <Zap className="h-3 w-3" />
                      {candidate.explanation.semantic_match}
                    </span>
                  </div>

                  {/* Skills match */}
                  <div className="mt-3">
                    <div className="flex items-center gap-2 mb-1.5">
                      <span className="text-xs font-medium">Skills Match ({candidate.skill_match_pct}%)</span>
                      <div className="flex-1 h-1.5 bg-slate-100 rounded-full overflow-hidden">
                        <div 
                          className={`h-full rounded-full ${
                            candidate.skill_match_pct >= 80 ? "bg-emerald-500" 
                            : candidate.skill_match_pct >= 60 ? "bg-blue-500" 
                            : "bg-amber-500"
                          }`}
                          style={{ width: `${candidate.skill_match_pct}%` }}
                        />
                      </div>
                    </div>
                    <div className="flex flex-wrap gap-1">
                      {candidate.matching_skills.slice(0, 5).map((skill) => (
                        <Badge key={skill} variant="secondary" className="text-xs font-normal bg-emerald-50 text-emerald-700 border-emerald-200">
                          <CheckCircle2 className="h-3 w-3 mr-0.5" />
                          {skill}
                        </Badge>
                      ))}
                      {candidate.missing_skills.slice(0, 3).map((skill) => (
                        <Badge key={skill} variant="secondary" className="text-xs font-normal bg-slate-50 text-slate-600 border-slate-200">
                          <X className="h-3 w-3 mr-0.5" />
                          {skill}
                        </Badge>
                      ))}
                      {candidate.matching_skills.length > 5 && (
                        <Badge variant="secondary" className="text-xs font-normal">+{candidate.matching_skills.length - 5} matched</Badge>
                      )}
                      {candidate.missing_skills.length > 3 && (
                        <Badge variant="secondary" className="text-xs font-normal">+{candidate.missing_skills.length - 3} gaps</Badge>
                      )}
                    </div>
                  </div>

                  {/* Experience summary */}
                  {candidate.experience_summary && (
                    <p className="mt-2 text-xs text-muted-foreground line-clamp-2">
                      {candidate.experience_summary}
                    </p>
                  )}
                </div>

                {/* Right: Actions */}
                <div className="flex sm:flex-col gap-2 p-4 pt-0 sm:pt-4 border-t sm:border-t-0 sm:border-l bg-slate-50/50 sm:w-44">
                  <Button 
                    size="sm" 
                    className="flex-1 sm:flex-none gap-1" 
                    onClick={() => handleInvite(candidate)}
                  >
                    <Send className="h-3.5 w-3.5" />
                    Invite to Apply
                  </Button>
                  <Button 
                    size="sm" 
                    variant="outline" 
                    className="flex-1 sm:flex-none gap-1"
                    onClick={() => handleMessage(candidate.candidate_id.toString())}
                  >
                    <MessageSquare className="h-3.5 w-3.5" />
                    Message
                  </Button>
                  <Button 
                    size="sm" 
                    variant="outline" 
                    className="flex-1 sm:flex-none gap-1"
                    onClick={() => handleViewProfile(candidate.candidate_id)}
                  >
                    <UserCheck className="h-3.5 w-3.5" />
                    View Profile
                  </Button>
                </div>
              </div>
            </Card>
          ))}
        </div>
      )}
    </div>
  )

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <h1 className="font-heading text-2xl font-bold">Candidates</h1>
          <p className="text-muted-foreground">Find and manage candidates</p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" size="sm" onClick={handleExport} className="gap-1">
            <Download className="h-4 w-4" />
            Export CSV
          </Button>
          <Button size="sm" className="gap-1" onClick={() => navigate("/recruiter/jobs/new")}>
            <Users className="h-4 w-4" />
            Post a Job
          </Button>
        </div>
      </div>

      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList className="flex-wrap h-auto">
          <TabsTrigger value="ai-search">
            <Sparkles className="h-3.5 w-3.5 mr-1.5" />
            AI Search
          </TabsTrigger>
          <TabsTrigger value="pipeline">
            <Users className="h-3.5 w-3.5 mr-1.5" />
            Pipeline
          </TabsTrigger>
        </TabsList>

        {/* AI Search Tab */}
        <TabsContent value="ai-search" className="mt-4">
          {selectedJobId ? renderCandidateSearch() : renderJobSelection()}
        </TabsContent>

        {/* Pipeline Tab */}
        <TabsContent value="pipeline" className="mt-4">
          {/* Stats */}
          {stats && (
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-5 mb-6">
              <ChartCard
                title="Total Candidates"
                value={stats.total}
                icon={<Users className="h-4 w-4" />}
              />
              <ChartCard
                title="New Applications"
                value={stats.new}
                trend="up"
                trendValue="+12%"
                icon={<Search className="h-4 w-4" />}
              />
              <ChartCard
                title="In Screening"
                value={stats.screening}
                icon={<SlidersHorizontal className="h-4 w-4" />}
              />
              <ChartCard
                title="Interviews"
                value={stats.interview}
                icon={<Calendar className="h-4 w-4" />}
              />
              <ChartCard
                title="Hired"
                value={stats.hired}
                trend="up"
                trendValue="+5%"
                icon={<UserCheck className="h-4 w-4" />}
              />
            </div>
          )}

          {/* Filters */}
          <FilterBar
            searchPlaceholder="Search by name, skill, or location..."
            onSearch={setSearchQuery}
            filters={filterOptions}
            activeFilters={activeFilters}
            onFilterChange={handleFilterChange}
            onClearFilters={handleClearFilters}
          />

          {/* Status Tabs */}
          <Tabs value={selectedTab} onValueChange={setSelectedTab} className="mt-4">
            <TabsList className="flex-wrap h-auto">
              <TabsTrigger value="all">
                All
                <Badge variant="secondary" className="ml-1 h-5 px-1.5 text-xs">{tabCounts.all}</Badge>
              </TabsTrigger>
              <TabsTrigger value="applied">
                Applied
                <Badge variant="secondary" className="ml-1 h-5 px-1.5 text-xs">{tabCounts.applied}</Badge>
              </TabsTrigger>
              <TabsTrigger value="screening">
                Screening
                <Badge variant="secondary" className="ml-1 h-5 px-1.5 text-xs">{tabCounts.screening}</Badge>
              </TabsTrigger>
              <TabsTrigger value="interview">
                Interview
                <Badge variant="secondary" className="ml-1 h-5 px-1.5 text-xs">{tabCounts.interview}</Badge>
              </TabsTrigger>
              <TabsTrigger value="offer">
                Offer
                <Badge variant="secondary" className="ml-1 h-5 px-1.5 text-xs">{tabCounts.offer}</Badge>
              </TabsTrigger>
            </TabsList>

            <TabsContent value={selectedTab} className="mt-4">
              {pipelineLoading ? (
                <div className="grid gap-4">
                  {Array.from({ length: 4 }).map((_, i) => (
                    <Skeleton key={i} variant="card" />
                  ))}
                </div>
              ) : filteredCandidates.length === 0 ? (
                <EmptyState
                  icon={Search}
                  title="No candidates found"
                  description={
                    searchQuery || Object.keys(activeFilters).length > 0
                      ? "Try adjusting your filters or search query"
                      : "Post a job to start receiving applications"
                  }
                  action={
                    searchQuery || Object.keys(activeFilters).length > 0
                      ? { label: "Clear filters", onClick: handleClearFilters }
                      : { label: "Post a job", href: "/recruiter/jobs" }
                  }
                />
              ) : (
                <div className="grid gap-4">
                  {filteredCandidates.map((candidate) => (
                    <div key={candidate.id} className="relative">
                      {candidate.applicationStatus && (
                        <Badge
                          className={`absolute top-3 right-3 z-10 ${statusColors[candidate.applicationStatus]}`}
                        >
                          {statusLabels[candidate.applicationStatus]}
                        </Badge>
                      )}
                      <CandidateCard
                        id={candidate.id}
                        name={candidate.name}
                        avatar={candidate.avatar}
                        headline={candidate.headline}
                        location={candidate.location}
                        experienceYears={candidate.experienceYears}
                        education={candidate.education}
                        skills={candidate.skills}
                        matchScore={candidate.matchScore}
                        omniscore={candidate.omniscore}
                        trustscore={candidate.trustscore}
                        isTopCandidate={candidate.isTopCandidate}
                        onMessage={handleMessage}
                        onSchedule={handleSchedule}
                        onShortlist={handleShortlist}
                      />
                    </div>
                  ))}
                </div>
              )}
            </TabsContent>
          </Tabs>
        </TabsContent>
      </Tabs>

      {/* Invite Dialog */}
      <Dialog open={showInviteDialog} onOpenChange={setShowInviteDialog}>
        <DialogHeader>
          <DialogTitle>Invite to Apply</DialogTitle>
          <DialogDescription>
            Send an invitation to {inviteCandidate?.name} to apply for {selectedJob?.title}
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4">
          {inviteSuccess ? (
            <div className="flex flex-col items-center gap-3 py-6">
              <div className="h-12 w-12 rounded-full bg-emerald-100 flex items-center justify-center">
                <CheckCircle2 className="h-6 w-6 text-emerald-600" />
              </div>
              <p className="font-medium text-center">Invitation sent!</p>
              <p className="text-sm text-muted-foreground text-center">
                {inviteCandidate?.name} will be notified about this opportunity.
              </p>
            </div>
          ) : (
            <>
              <div className="flex items-center gap-3 p-3 rounded-lg bg-slate-50">
                <div className="h-10 w-10 rounded-full bg-primary/10 flex items-center justify-center text-primary font-semibold text-sm">
                  {inviteCandidate?.name.split(" ").map(n => n[0]).join("").toUpperCase().slice(0, 2)}
                </div>
                <div>
                  <p className="font-medium text-sm">{inviteCandidate?.name}</p>
                  <p className="text-xs text-muted-foreground">
                    {Math.round(inviteCandidate?.weighted_score || 0)}% match — {inviteCandidate?.match_level}
                  </p>
                </div>
              </div>

              <div>
                <label className="text-sm font-medium mb-1.5 block">Personal Message</label>
                <Textarea
                  value={inviteMessage}
                  onChange={(e) => setInviteMessage(e.target.value)}
                  rows={4}
                  placeholder="Write a personalized message to the candidate..."
                />
                <p className="text-xs text-muted-foreground mt-1.5">
                  This message will be sent to the candidate via email and in-app notification.
                </p>
              </div>

              <div className="flex gap-2 justify-end">
                <Button variant="outline" onClick={() => setShowInviteDialog(false)}>
                  Cancel
                </Button>
                <Button 
                  onClick={handleSendInvite} 
                  disabled={inviteLoading || !inviteMessage.trim()}
                  className="gap-1"
                >
                  {inviteLoading ? (
                    <>
                      <div className="h-3.5 w-3.5 animate-spin rounded-full border-2 border-current border-t-transparent" />
                      Sending...
                    </>
                  ) : (
                    <>
                      <Send className="h-3.5 w-3.5" />
                      Send Invite
                    </>
                  )}
                </Button>
              </div>
            </>
          )}
        </div>
      </Dialog>
    </div>
  )
}

