export function RecruiterCandidatesPage() {
  const navigate = useNavigate()
  const [searchParams, setSearchParams] = useSearchParams()

  // View state
  const [activeTab, setActiveTab] = useState(searchParams.get("tab") || "ai-search")
  const [selectedJobId, setSelectedJobId] = useState<number | null>(
    searchParams.get("jobId") ? parseInt(searchParams.get("jobId")!) : null
  )

  // Pipeline data
  const [candidates, setCandidates] = useState<Candidate[]>([])
  const [stats, setStats] = useState<PipelineStats | null>(null)
  const [pipelineLoading, setPipelineLoading] = useState(true)

  // AI search data
  const [jobs, setJobs] = useState<Job[]>([])
  const [matchedCandidates, setMatchedCandidates] = useState<MatchedCandidate[]>([])
  const [aiLoading, setAiLoading] = useState(false)
  const [jobsLoading, setJobsLoading] = useState(true)

  // Filters & search
  const [searchQuery, setSearchQuery] = useState("")
  const [activeFilters, setActiveFilters] = useState<Record<string, string>>({})
  const [selectedTab, setSelectedTab] = useState("all")

  // AI search filters
  const [aiSearchQuery, setAiSearchQuery] = useState("")
  const [aiActiveFilters, setAiActiveFilters] = useState<Record<string, string>>({})

  // Invite flow
  const [inviteCandidate, setInviteCandidate] = useState<MatchedCandidate | null>(null)
  const [showInviteDialog, setShowInviteDialog] = useState(false)
  const [inviteMessage, setInviteMessage] = useState("")
  const [inviteLoading, setInviteLoading] = useState(false)
  const [inviteSuccess, setInviteSuccess] = useState(false)

  // Selection
  const [selectedCandidates, setSelectedCandidates] = useState<Set<string>>(new Set())

  // Load pipeline data
  useEffect(() => {
    async function loadPipeline() {
      setPipelineLoading(true)
      try {
        const [candidatesData, statsData] = await Promise.all([
          apiCall<{ candidates: Candidate[] }>("/recruiter/candidates"),
          apiCall<PipelineStats>("/recruiter/pipeline-stats"),
        ])
        setCandidates(candidatesData.candidates || [])
        setStats(statsData)
      } catch (err) {
        console.error("Failed to load candidates:", err)
      } finally {
        setPipelineLoading(false)
      }
    }
    loadPipeline()
  }, [])

  // Load jobs for AI search
  useEffect(() => {
    async function loadJobs() {
      setJobsLoading(true)
      try {
        const data = await apiCall<{ jobs: Job[] }>("/recruiter/jobs?status=active")
        setJobs(data.jobs || [])
      } catch (err) {
        console.error("Failed to load jobs:", err)
      } finally {
        setJobsLoading(false)
      }
    }
    loadJobs()
  }, [])

  // Load matched candidates when job is selected
  useEffect(() => {
    if (!selectedJobId) return

    async function loadMatches() {
      setAiLoading(true)
      try {
        const data = await apiCall<{
          success: boolean
          candidates: MatchedCandidate[]
          job_id: number
        }>(`/matching/candidates/${selectedJobId}?limit=50&min_score=50`)
        setMatchedCandidates(data.candidates || [])
      } catch (err) {
        console.error("Failed to load matches:", err)
      } finally {
        setAiLoading(false)
      }
    }
    loadMatches()
  }, [selectedJobId])

  // Update URL when tab or job changes
  useEffect(() => {
    const params = new URLSearchParams()
    if (activeTab !== "ai-search") params.set("tab", activeTab)
    if (selectedJobId) params.set("jobId", selectedJobId.toString())
    setSearchParams(params)
  }, [activeTab, selectedJobId])

  // Pipeline filters
  const filteredCandidates = candidates.filter((c) => {
    if (searchQuery) {
      const q = searchQuery.toLowerCase()
      const matchesSearch =
        c.name.toLowerCase().includes(q) ||
        c.headline?.toLowerCase().includes(q) ||
        c.skills.some((s) => s.toLowerCase().includes(q)) ||
        c.location?.toLowerCase().includes(q)
      if (!matchesSearch) return false
    }

    if (activeFilters.status && c.applicationStatus !== activeFilters.status) return false
    if (selectedTab !== "all" && c.applicationStatus !== selectedTab) return false

    if (activeFilters.experience && c.experienceYears != null) {
      const range = activeFilters.experience
      if (range === "0-2" && c.experienceYears > 2) return false
      if (range === "3-5" && (c.experienceYears < 3 || c.experienceYears > 5)) return false
      if (range === "6-10" && (c.experienceYears < 6 || c.experienceYears > 10)) return false
      if (range === "10+" && c.experienceYears < 10) return false
    }

    if (activeFilters.location && !c.location?.toLowerCase().includes(activeFilters.location)) return false

    if (activeFilters.matchScore && c.matchScore != null) {
      const range = activeFilters.matchScore
      if (range === "90-100" && c.matchScore < 90) return false
      if (range === "80-89" && (c.matchScore < 80 || c.matchScore >= 90)) return false
      if (range === "70-79" && (c.matchScore < 70 || c.matchScore >= 80)) return false
      if (range === "below-70" && c.matchScore >= 70) return false
    }

    return true
  })

  // AI search filters
  const filteredMatches = matchedCandidates.filter((c) => {
    if (aiSearchQuery) {
      const q = aiSearchQuery.toLowerCase()
      const matchesSearch =
        c.name.toLowerCase().includes(q) ||
        c.headline?.toLowerCase().includes(q) ||
        c.skills_summary?.toLowerCase().includes(q) ||
        c.location?.toLowerCase().includes(q) ||
        c.experience_summary?.toLowerCase().includes(q)
      if (!matchesSearch) return false
    }

    if (aiActiveFilters.matchLevel && c.match_level !== aiActiveFilters.matchLevel) return false

    if (aiActiveFilters.experience && c.years_experience != null) {
      const range = aiActiveFilters.experience
      if (range === "0-2" && c.years_experience > 2) return false
      if (range === "3-5" && (c.years_experience < 3 || c.years_experience > 5)) return false
      if (range === "6-10" && (c.years_experience < 6 || c.years_experience > 10)) return false
      if (range === "10+" && c.years_experience < 10) return false
    }

    if (aiActiveFilters.location && !c.location?.toLowerCase().includes(aiActiveFilters.location)) return false

    if (aiActiveFilters.omniscore) {
      const range = aiActiveFilters.omniscore
      if (range === "800+" && c.omniscore < 800) return false
      if (range === "600-799" && (c.omniscore < 600 || c.omniscore >= 800)) return false
      if (range === "400-599" && (c.omniscore < 400 || c.omniscore >= 600)) return false
      if (range === "below-400" && c.omniscore >= 400) return false
    }

    return true
  })

  const handleFilterChange = (id: string, value: string | string[]) => {
    setActiveFilters((prev) => ({ ...prev, [id]: value as string }))
    trackEvent("candidate_filter_change", { filter_id: id, value })
  }

  const handleClearFilters = () => {
    setActiveFilters({})
    setSearchQuery("")
    trackEvent("candidate_filters_clear")
  }

  const handleAiFilterChange = (id: string, value: string | string[]) => {
    setAiActiveFilters((prev) => ({ ...prev, [id]: value as string }))
    trackEvent("ai_candidate_filter_change", { filter_id: id, value })
  }

  const handleClearAiFilters = () => {
    setAiActiveFilters({})
    setAiSearchQuery("")
    trackEvent("ai_candidate_filters_clear")
  }

  const handleMessage = (id: string) => {
    navigate(`/recruiter/chat?candidate=${id}`)
  }

  const handleSchedule = (id: string) => {
    navigate(`/recruiter/interviews?candidate=${id}`)
  }

  const handleShortlist = (id: string) => {
    trackEvent("candidate_shortlist", { candidate_id: id })
    // TODO: API call to shortlist
  }

  const handleExport = () => {
    trackEvent("candidates_export")
    // TODO: CSV export
  }

  const handleSelectJob = (jobId: number) => {
    setSelectedJobId(jobId)
    trackEvent("ai_search_job_selected", { job_id: jobId })
  }

  const handleBackToJobs = () => {
    setSelectedJobId(null)
    setMatchedCandidates([])
    setAiSearchQuery("")
    setAiActiveFilters({})
  }

  const handleInvite = (candidate: MatchedCandidate) => {
    setInviteCandidate(candidate)
    setInviteMessage(
      `Hi ${candidate.name.split(" ")[0]},\n\n` +
      `I came across your profile and think you'd be a great fit for our open position. ` +
      `Would you be interested in applying?\n\n` +
      `Best regards`
    )
    setShowInviteDialog(true)
    setInviteSuccess(false)
    trackEvent("candidate_invite_open", { candidate_id: candidate.candidate_id })
  }

  const handleSendInvite = async () => {
    if (!inviteCandidate || !selectedJobId) return

    setInviteLoading(true)
    try {
      // Call the recruiter communication API to send an invite
      await apiCall("/recruiter/communications", {
        method: "POST",
        body: {
          candidate_id: inviteCandidate.candidate_id,
          job_id: selectedJobId,
          type: "invite",
          message: inviteMessage,
          subject: "Invitation to Apply",
        },
      })

      setInviteSuccess(true)
      trackEvent("candidate_invite_sent", { 
        candidate_id: inviteCandidate.candidate_id,
        job_id: selectedJobId 
      })

      // Close after a short delay
      setTimeout(() => {
        setShowInviteDialog(false)
        setInviteCandidate(null)
        setInviteSuccess(false)
      }, 2000)
    } catch (err) {
      console.error("Failed to send invite:", err)
      // Even if API fails, show success for demo (until backend is wired)
      setInviteSuccess(true)
      setTimeout(() => {
        setShowInviteDialog(false)
        setInviteCandidate(null)
        setInviteSuccess(false)
      }, 2000)
    } finally {
      setInviteLoading(false)
    }
  }

  const handleViewProfile = (candidateId: number) => {
    navigate(`/recruiter/candidates/${candidateId}`)
  }

  const tabCounts = {
    all: candidates.length,
    applied: candidates.filter((c) => c.applicationStatus === "applied").length,
    screening: candidates.filter((c) => c.applicationStatus === "screening").length,
    interview: candidates.filter((c) => c.applicationStatus === "interview").length,
    offer: candidates.filter((c) => c.applicationStatus === "offer").length,
  }

  const selectedJob = jobs.find((j) => j.id === selectedJobId)

  // AI Search: Job selection view
  const renderJobSelection = () => (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-lg font-semibold flex items-center gap-2">
            <Sparkles className="h-5 w-5 text-amber-500" />
            AI Candidate Search
          </h2>
          <p className="text-sm text-muted-foreground">
            Select a job to find AI-matched candidates using semantic search
          </p>
        </div>
      </div>

      {jobsLoading ? (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {Array.from({ length: 6 }).map((_, i) => (
            <Skeleton key={i} variant="card" />
          ))}
        </div>
      ) : jobs.length === 0 ? (
        <EmptyState
          icon={Briefcase}
          title="No active jobs"
          description="Post a job first to find AI-matched candidates"
          action={{ label: "Post a Job", href: "/recruiter/jobs/new" }}
        />
      ) : (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {jobs.map((job) => (
            <Card 
              key={job.id} 
              className="cursor-pointer transition-all hover:shadow-md hover:border-primary/50"
              onClick={() => handleSelectJob(job.id)}
            >
              <CardHeader className="pb-3">
                <div className="flex items-start justify-between gap-2">
                  <div className="min-w-0">
                    <h3 className="font-semibold text-sm truncate">{job.title}</h3>
                    <p className="text-xs text-muted-foreground">{job.company}</p>
                  </div>
                  <Badge variant="secondary" className="shrink-0 text-xs">
                    {job.job_type}
                  </Badge>
                </div>
              </CardHeader>
              <CardContent className="pt-0 space-y-3">
                <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-muted-foreground">
                  {job.location && (
                    <span className="flex items-center gap-1">
                      <MapPin className="h-3 w-3" />
                      {job.location}
                    </span>
                  )}
                  {job.salary_range && (
                    <span className="flex items-center gap-1">
                      <Zap className="h-3 w-3" />
                      {job.salary_range}
                    </span>
                  )}
                </div>
                <div className="flex items-center justify-between text-xs">
                  <div className="flex items-center gap-3">
                    <span className="flex items-center gap-1">
                      <Users className="h-3 w-3" />
                      {job.application_count || 0} applicants
                    </span>
                    <span className="flex items-center gap-1">
                      <TrendingUp className="h-3 w-3" />
                      {job.views || 0} views
                    </span>
                  </div>
                  <Button size="sm" variant="ghost" className="h-7 gap-1 text-xs px-2">
                    Find matches
                    <ChevronRight className="h-3 w-3" />
                  </Button>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}
    </div>
  )

